'use strict';
const KEY='forge-state-v1', $=s=>document.querySelector(s), uid=()=>crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join(''), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catalog=[['Bench press','Chest','Barbell'],['Incline dumbbell press','Chest','Dumbbell'],['Push-up','Chest','Bodyweight'],['Cable fly','Chest','Cable'],['Back squat','Legs','Barbell'],['Goblet squat','Legs','Dumbbell'],['Leg press','Legs','Machine'],['Romanian deadlift','Legs','Barbell'],['Walking lunge','Legs','Dumbbell'],['Leg curl','Legs','Machine'],['Calf raise','Legs','Machine'],['Deadlift','Back','Barbell'],['Lat pulldown','Back','Cable'],['Pull-up','Back','Bodyweight'],['Seated cable row','Back','Cable'],['Dumbbell row','Back','Dumbbell'],['Overhead press','Shoulders','Barbell'],['Lateral raise','Shoulders','Dumbbell'],['Face pull','Shoulders','Cable'],['Biceps curl','Arms','Dumbbell'],['Hammer curl','Arms','Dumbbell'],['Triceps pushdown','Arms','Cable'],['Plank','Core','Bodyweight'],['Crunch','Core','Bodyweight'],['Hanging knee raise','Core','Bodyweight'],['Running','Cardio','Bodyweight']].map(([name,muscle,equipment],i)=>({id:String(i),name,muscle,equipment}));
catalog[2].demoKey='pushup';catalog[5].demoKey='squat';catalog[7].demoKey='hinge';catalog[15].demoKey='row';
catalog[22].kind='timed';catalog[25].kind='cardio';for(const e of ForgeTraining.exercises||[])if(!catalog.some(c=>c.name.toLowerCase()===e.name.toLowerCase()))catalog.push({...e});
for(const e of globalThis.ForgeExerciseLibrary||[]){const known=catalog.find(c=>c.name.toLowerCase()===e.name.toLowerCase());if(known){known.instructions=e.instructions;known.bodyPart=e.bodyPart}else catalog.push({...e,...(e.bodyPart==='cardio'?{kind:'cardio'}:/^(plank|side plank)$/i.test(e.name)?{kind:'timed'}:{})})}
const demoNames={squat:'Squat pattern',pushup:'Push-up',row:'Dumbbell row',hinge:'Hip hinge pattern',bridge:'Glute bridge',deadbug:'Dead bug'};
const empty=()=>({version:1,workouts:[],routines:[],bodyweight:[],active:null,settings:{unit:'kg',rest:90}});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||empty()}catch{state=empty()}let page='home',demo=false,user=null,installPrompt=null,syncQueue=Promise.resolve(),cloudEpoch=0,revision=0,syncConflict=false;
function valid(s) {
  const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
  const string = (value, max, required = false) => typeof value === 'string' && value.length <= max && (!required || value.length > 0);
  const number = (value,min,max) => Number.isFinite(value) && value >= min && value <= max;
  const timestamp = value => number(value,0,8640000000000000);
  const optional = (value,check) => value === undefined || check(value);
  const set = value => object(value) && number(value.reps,0,10000) && optional(value.seconds,v=>number(v,0,86400)) && optional(value.distanceKm,v=>number(v,0,1000)) && number(value.weight,0,10000) && (value.rpe === null || number(value.rpe,0,10)) && typeof value.done === 'boolean';
  const exercise = value => object(value) && optional(value.kind,v=>['reps','timed','cardio'].includes(v)) && optional(value.demoKey,v=>Object.hasOwn(demoNames,v)) && string(value.id,100,true) && string(value.name,200) && string(value.muscle,100) && string(value.equipment,100) && optional(value.notes,v=>string(v,2000)) && Array.isArray(value.sets) && value.sets.length <= 100 && value.sets.every(set);
  const exercises = value => Array.isArray(value) && value.length <= 100 && value.every(exercise);
  const routine = value => object(value) && string(value.id,100,true) && string(value.name,200) && exercises(value.exercises);
  const workout = value => routine(value) && timestamp(value.started) && optional(value.finished,timestamp) && optional(value.restUntil,timestamp) && optional(value.notes,v=>string(v,2000));
  const profileOK = value => {try { ForgeTraining.validateProfile(value);return true } catch {return false}};
  const unique = values => new Set(values.map(value=>value?.id)).size === values.length;
  return object(s) && optional(s.profilePlanIds,v=>Array.isArray(v)&&v.length<=6&&new Set(v).size===v.length&&v.every(id=>string(id,100,true))) && optional(s.profile,profileOK) && s.version === 1 && Array.isArray(s.workouts) && s.workouts.length <= 10000 && s.workouts.every(workout) && unique(s.workouts) && Array.isArray(s.routines) && s.routines.length <= 1000 && s.routines.every(routine) && unique(s.routines) && Array.isArray(s.bodyweight) && s.bodyweight.length <= 10000 && s.bodyweight.every(value=>object(value) && string(value.id,100,true) && timestamp(value.date) && number(value.weight,Number.MIN_VALUE,1000)) && unique(s.bodyweight) && (s.active === null || workout(s.active)) && object(s.settings) && ['kg','lb'].includes(s.settings.unit) && number(s.settings.rest,0,600);
}
if(!valid(state))state=empty();
let cachedAccount=null;if(localStorage.getItem('forge-mode')==='account'){cachedAccount=state;try{state=JSON.parse(localStorage.getItem('forge-local-backup'))||empty()}catch{state=empty()}if(!valid(state))state=empty()}let mutationCount=0;

function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function save(){mutationCount++;try{localStorage.setItem(user?'forge-account-'+user.id:KEY,JSON.stringify(state));localStorage.setItem('forge-mode','local')}catch{toast('Device storage is full. Export a backup.')}if(user){if(syncConflict){$('#sync-status').textContent='Sync conflict · export then reload';return}const snapshot=structuredClone(state),epoch=cloudEpoch;$('#sync-status').textContent='Syncing…';syncQueue=syncQueue.then(async()=>{if(epoch!==cloudEpoch||syncConflict)return;try{const r=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:snapshot,revision})});if(r.status===409){syncConflict=true;$('#sync-status').textContent='Sync conflict · export then reload';toast('Another device changed your journal. Export your changes, then reload.');return}if(!r.ok)throw Error();const d=await r.json();revision=d.revision;if(epoch===cloudEpoch)$('#sync-status').textContent='Account saved'}catch{if(epoch===cloudEpoch)$('#sync-status').textContent='Sync failed · saved locally'}})}else $('#sync-status').textContent='Saved on this device'}

const unit=()=>state.settings.unit, weight=n=>unit()==='lb'?Math.round(n*2.20462*10)/10:n, kg=n=>unit()==='lb'?n/2.20462:n, fmt=n=>Math.round(n).toLocaleString(), date=n=>new Date(n).toLocaleDateString(undefined,{month:'short',day:'numeric'}), sets=w=>w.exercises.flatMap(e=>e.sets).filter(s=>s.done), volume=w=>w.exercises.filter(e=>!['timed','cardio'].includes(e.kind)).flatMap(e=>e.sets).filter(s=>s.done).reduce((n,s)=>n+s.reps*s.weight,0);
function sample(){const d=empty();d.workouts=[0,2,4,7,9,11].map((days,i)=>({id:'demo'+i,name:i%2?'Lower body strength':'Upper body strength',started:Date.now()-days*86400000-2400000,finished:Date.now()-days*86400000,notes:'',exercises:[0,4,12].map(j=>({...catalog[j],sets:[1,2,3].map(()=>({reps:10,weight:30+i*2,rpe:8,done:true})),notes:''}))}));return d}
function view(){return demo?sample():state}const navs=[['home','◫','Overview'],['routines','▤','Routines'],['history','◷','History'],['progress','↗','Progress'],['settings','⚙','Settings']];
function render(){for(const id of ['desktop-nav','mobile-nav'])$('#'+id).innerHTML=navs.map(([p,i,n])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}><span class="nav-icon">${i}</span>${n}</button>`).join('');$('#mode-label').textContent=user?'Account mode':'Local device mode';$('#content').innerHTML=(demo?'<div class="demo-banner">Sample data preview · nothing is added to your journal.<button class="ghost" data-action="demo">Exit demo</button></div>':'')+({home:home,routines:routines,history:history,progress:progress,settings:settings,session:session}[page]||home)();updateTimer()}
function heading(k,t,p,action=''){return `<div class="page-heading"><div><div class="kicker">${k}</div><h1>${t}</h1><p>${p}</p></div>${action}</div>`}
function home(){const s=view(),goal=s.profile?(ForgeTraining.recommend(s.profile).weeklyGoal||null):3,total=s.workouts,week=total.filter(w=>w.started>=Date.now()-7*86400000).length,count=total.reduce((n,w)=>n+sets(w).length,0);return heading('YOUR NEXT CHAPTER','Make progress.','Small steps. Stronger every day.',`<div class="heading-actions"><button class="secondary" data-action="quick-log">＋ Quick log</button><button data-action="start">${state.active?'Resume workout':'＋ Start workout'}</button></div>`)+planCard(s)+`<section class="hero"><div class="hero-copy"><div class="kicker">SHOW UP FOR YOURSELF</div><h2>The best workout is<br>the one you do.</h2><p>Your personal training space. Log the work, find your rhythm, and watch your strength grow.</p><button class="lime" data-action="start">${state.active?'Resume session':'Let’s get moving'} &nbsp; ↗</button></div><div class="hero-art" aria-hidden="true"><div class="bar"></div><div class="plate left"></div><div class="plate right"></div><div class="plate small left"></div><div class="plate small right"></div></div></section>${GymProgress.render(total,count)}<div class="stats">${stat('This week',week,goal?`of ${goal} sessions goal`:'Sessions logged')}${stat('Workouts logged',total.length,'Every session counts')}${stat('Total volume',fmt(weight(total.reduce((n,w)=>n+volume(w),0))),unit()+' lifted across all sessions')}${stat('Current streak',GymProgress.streakDays(total),'consecutive training days')}</div><div class="grid"><section class="card"><div class="card-title"><h2>Recent activity</h2><button class="ghost" data-page="history">View journal ↗</button></div>${total.length?total.slice().sort((a,b)=>b.started-a.started).slice(0,3).map(w=>workoutRow(w,false)).join(''):`<div class="empty"><div class="empty-icon">◷</div><h3>Your story starts here.</h3><p>Log your first workout. Your completed sessions and personal bests will live here.</p><button class="secondary" data-action="demo">Explore with sample data</button></div>`}</section><section class="card"><div class="card-title"><h2>Your weekly rhythm</h2><span class="tag">${goal?goal+' SESSION GOAL':'YOUR RHYTHM'}</span></div><p class="subtle">Consistency builds strength. One day at a time.</p><div class="goal-days">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const done=total.some(w=>new Date(w.started).toDateString()===d.toDateString());return `<div class="day"><span class="${done?'done':''}">${done?'✓':d.getDate()}</span>${d.toLocaleDateString(undefined,{weekday:'short'}).slice(0,1)}</div>`}).join('')}</div><progress class="progress-track" value="${goal?Math.min(goal,week):0}" max="${goal||1}" aria-label="Weekly workout goal"></progress><div class="row"><span class="subtle">${!goal?'Set a goal with your trainer.':week>=goal?'Weekly goal achieved. Keep it going.':`${Math.max(0,goal-week)} sessions to your weekly goal`}</span><strong>${goal?week+'/'+goal:week+' logged'}</strong></div></section></div><div class="notice">${user?'Account mode: your journal syncs when connected.':'Private by default. Your journal stays on this device. Export a backup or enable an account in Settings.'}</div>`}
function quickLog(){if(state.active){page='session';render();return toast('Finish or discard your active session before quick-logging.')}modal('Quick log',`<form id="quick-log-form"><label for="quick-log-name">Session name</label><input id="quick-log-name" maxlength="200" value="Workout" required><div class="form-grid"><div><label for="quick-log-duration">Duration (minutes)</label><input id="quick-log-duration" type="number" min="1" max="600" value="30" required></div><div><label for="quick-log-notes">Notes</label><input id="quick-log-notes" maxlength="2000" placeholder="Optional"></div></div><div class="button-row section-space"><button type="submit" class="lime">Save quick log</button><button type="button" class="ghost" data-action="close">Cancel</button></div></form>`);$('#quick-log-form').onsubmit=e=>{e.preventDefault();const name=$('#quick-log-name').value.trim(),minutes=Number($('#quick-log-duration').value),notes=$('#quick-log-notes').value.trim();if(!name||!Number.isInteger(minutes)||minutes<1||minutes>600)return toast('Enter a name and a duration from 1 to 600 minutes.');const finished=Date.now();state.workouts.push({id:uid(),name,exercises:[],started:finished-minutes*60000,finished,notes});save();$('#modal').close();render();toast('Quick log saved. +80 XP earned.')}}
function stat(l,n,s){return `<div class="stat"><span class="label">${l}</span><strong>${n}</strong><small>${s}</small></div>`}
function workoutRow(w,actions=true){return `<div class="row"><div><h3>${esc(w.name)}</h3><p>${date(w.started)} · ${sets(w).length} sets · ${fmt(weight(volume(w)))} ${unit()} volume · ${Math.max(1,Math.round(((w.finished||w.started)-w.started)/60000))} min</p></div>${actions?`<div class="history-actions"><button class="ghost" data-action="edit-workout" data-id="${esc(w.id)}">Edit</button><button class="danger" data-action="delete-workout" data-id="${esc(w.id)}">Delete</button></div>`:'<span class="tag">COMPLETE</span>'}</div>`}
const templates=[{name:'Full body foundations',ids:[4,0,12,17,23]},{name:'Upper body strength',ids:[0,15,16,19,21]},{name:'Lower body strength',ids:[4,7,8,9,10]}];
function routines(){return heading('A PLAN THAT FITS YOU','Train with intention.','Save your go-to sessions. Spend less time planning.',`<button data-action="new-routine">＋ New routine</button>`)+`<div class="routine-grid">${state.routines.map(r=>`<section class="card routine-card"><span class="tag">YOUR ROUTINE</span><h3>${esc(r.name)}</h3><p>${r.exercises.map(e=>esc(e.name)).join(' · ')}</p><div class="button-row"><button class="lime" data-action="use-routine" data-id="${esc(r.id)}">Start</button><button class="ghost" data-action="edit-routine" data-id="${esc(r.id)}">Edit</button><button class="danger" data-action="delete-routine" data-id="${esc(r.id)}">Delete</button></div></section>`).join('')}</div><div class="section-space"><h2>Start with a blueprint</h2><p>Simple starter templates. Adjust exercises and sets to suit you.</p><div class="routine-grid section-space">${templates.map((t,i)=>`<section class="card routine-card"><span class="tag">STARTER / 0${i+1}</span><h3>${t.name}</h3><p>${t.ids.length} exercises · ${t.ids.map(j=>catalog[j].muscle).filter((a,i,x)=>x.indexOf(a)===i).join(' / ')}</p><div class="button-row"><button class="secondary" data-action="template" data-id="${i}">Use template ↗</button></div></section>`).join('')}</div></div>`}
function history(){const w=view().workouts.slice().sort((a,b)=>b.started-a.started);return heading('EVERY REP HAS A RECORD','Your training journal.','A clear view of the work you’ve put in.')+`<section class="card">${w.length?w.map(x=>workoutRow(x)).join(''):'<div class="empty"><div class="empty-icon">▤</div><h3>A fresh page.</h3><p>Complete a workout to start your training history.</p><button data-action="start">Start your first workout</button></div>'}</section>`}
function progress(){const w=view().workouts,pr=Object.create(null);w.forEach(x=>x.exercises.filter(e=>!e.kind||e.kind==='rep').forEach(e=>e.sets.filter(s=>s.done).forEach(s=>{if(!pr[e.name]||pr[e.name].weight<s.weight)pr[e.name]=s})));const last=w.slice().sort((a,b)=>a.started-b.started).slice(-7),max=Math.max(1,...last.map(volume));return heading('THE BIGGER PICTURE','See your strength grow.','Progress is personal. Your data tells your story.')+`<div class="stats">${stat('Completed sessions',w.length,'All time')}${stat('Completed sets',w.reduce((n,x)=>n+sets(x).length,0),'Quality reps add up')}${stat('Personal records',Object.keys(pr).length,'Heaviest completed sets')}${stat('Latest bodyweight',state.bodyweight.length?weight(state.bodyweight.at(-1).weight).toFixed(1):'—',unit())}</div><div class="grid"><section class="card"><h2>Session volume</h2><p class="subtle">Completed reps × weight (${unit()}). Bodyweight resistance is excluded.</p>${last.length?`<div class="chart">${last.map(x=>`<div class="chart-bar height-${Math.max(1,Math.round(volume(x)/max*20))}"><b>${fmt(weight(volume(x)))}</b><span>${date(x.started)}</span></div>`).join('')}</div><br><br>`:'<div class="empty"><p>Your volume chart appears after your first session.</p></div>'}</section><section class="card"><div class="card-title"><h2>Bodyweight journal</h2><button class="ghost" data-action="bodyweight">＋ Log</button></div>${state.bodyweight.length?state.bodyweight.slice(-5).reverse().map(b=>`<div class="row"><span>${date(b.date)}</span><strong>${weight(b.weight).toFixed(1)} ${unit()}</strong><button class="ghost" data-action="delete-weight" data-id="${esc(b.id)}" aria-label="Delete bodyweight entry">×</button></div>`).join(''):'<p class="subtle">Optional. Track bodyweight on your own terms.</p>'}</section></div><section class="card section-space"><h2>Personal records</h2><p class="subtle">Heaviest external weight logged per exercise.</p>${Object.entries(pr).length?Object.entries(pr).map(([n,s])=>`<div class="row"><strong>${esc(n)}</strong><span>${weight(s.weight).toFixed(1)} ${unit()} × ${s.reps} reps</span></div>`).join(''):'<div class="empty"><p>Complete sets to discover your personal bests.</p></div>'}</section>`}
function settings(){return heading('MAKE IT YOURS','Your space. Your rules.','Preferences, backups, and optional account sync.')+`<div class="settings-grid"><section class="card"><h2>Training preferences</h2><p class="subtle">Choose a goal, schedule and equipment. Optional measurements stay in your journal.</p><button class="secondary" data-action="setup">${state.profile?'Edit your training profile':'Personalize my plan'}</button><div class="setting-row"><label for="unit">Weight unit</label><select id="unit"><option ${unit()==='kg'?'selected':''}>kg</option><option ${unit()==='lb'?'selected':''}>lb</option></select></div><div class="setting-row"><label for="rest">Rest timer (seconds)</label><input id="rest" type="number" min="0" max="600" value="${state.settings.rest}"></div><p class="help">Weights are stored in kilograms and converted for display.</p></section><section class="card"><h2>${user?'Your account':'Optional account sync'}</h2><p>${user?esc(user.email):'Local mode works without an account. Enable secure server sync when you’re ready.'}</p><div class="notice">${user?'This device keeps a working copy. Sync status is shown at the top.':'Local data is stored in this browser. Clearing browser data removes it. Export regularly.'}</div><div class="button-row">${user?'<button class="ghost" data-action="logout">Sign out</button><button class="ghost" data-action="reload-account">Reload account journal</button>':'<button data-action="login">Sign in</button><button class="ghost" data-action="register">Create account</button>'}</div></section><section class="card"><h2>Your data</h2><p class="help">Backups include routines, workouts, bodyweight, your training profile, and your active session.</p><div class="button-row section-space"><button class="secondary" data-action="export">Export JSON</button><button class="ghost" data-action="import">Import backup</button><button class="danger" data-action="clear">Clear journal</button></div><input id="import-file" type="file" accept="application/json,.json" hidden></section><section class="card"><h2>Take GYM with you.</h2><p>Install as an app for a focused, full-screen experience.</p><button class="secondary" data-action="install">Install app ↗</button><p class="help">iPhone: open in Safari → Share → Add to Home Screen. Android / desktop: use your browser’s Install app option. HTTPS is required.</p></section></div><div class="notice">Nutrition is coming in a later phase. This release is focused on your training journal.</div>`}
function newExercise(c){const {instructions,cues,bodyPart,...metadata}=c;return {...metadata,notes:c.notes||'',sets:Array.from({length:c.kind==='cardio'?1:3},()=>({reps:['timed','cardio'].includes(c.kind)?0:10,weight:0,rpe:null,done:false,...(['timed','cardio'].includes(c.kind)?{seconds:c.kind==='cardio'?600:30}:{}),...(c.kind==='cardio'?{distanceKm:0}:{})}))}}
function start(exercises=[],name='My workout'){if(demo){demo=false;toast('Left sample preview. Your actual journal is active.')}if(!state.active){state.active={id:uid(),name,started:Date.now(),exercises:structuredClone(exercises),notes:'',restUntil:0};save()}page='session';render()}
function session(){const w=state.active;if(!w){page='home';return home()}return heading('LIVE SESSION', 'Make every rep count.',`${date(w.started)} · Started ${new Date(w.started).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})}`,`<button class="lime" data-action="finish">Finish workout ✓</button>`)+`<input class="workout-title" aria-label="Workout name" maxlength="200" data-session="name" value="${esc(w.name)}"><div class="timer"><span>Rest timer <strong id="timer-value">Ready</strong></span><div class="button-row"><button class="secondary" data-action="rest">Start ${state.settings.rest}s</button><button class="ghost" data-action="stop-rest">Stop</button></div></div>${w.exercises.map((e,i)=>`<section class="card exercise-card"><div class="exercise-head"><div><h3>${esc(e.name)}</h3><span class="subtle">${esc(e.muscle)} / ${esc(e.equipment)}</span></div>${guideButton(e)}<button class="ghost" data-action="remove-exercise" data-i="${i}" aria-label="Remove ${esc(e.name)}">×</button></div><div class="set-header"><span>SET</span><span>${e.kind==='cardio'?'KM':unit().toUpperCase()}</span><span>${['timed','cardio'].includes(e.kind)?'SECONDS':'REPS'}</span><span>RPE</span><span>DONE</span><span></span></div>${e.sets.map((s,j)=>`<div class="set-row"><span class="subtle">${j+1}</span><input aria-label="Set ${j+1} ${e.kind==='cardio'?'distance in kilometres':'weight'}" type="number" min="0" max="${e.kind==='cardio'?1000:10000}" step="${e.kind==='cardio'?0.01:0.5}" value="${e.kind==='cardio'?(s.distanceKm||0):Math.round(weight(s.weight)*10)/10}" data-i="${i}" data-j="${j}" data-set="${e.kind==='cardio'?'distanceKm':'weight'}"><input aria-label="Set ${j+1} ${['timed','cardio'].includes(e.kind)?'seconds':'reps'}" type="number" min="0" max="${['timed','cardio'].includes(e.kind)?86400:10000}" value="${['timed','cardio'].includes(e.kind)?(s.seconds||0):s.reps}" data-i="${i}" data-j="${j}" data-set="${['timed','cardio'].includes(e.kind)?'seconds':'reps'}"><input aria-label="Set ${j+1} RPE" type="number" min="0" max="10" step="0.5" placeholder="—" value="${s.rpe??''}" data-i="${i}" data-j="${j}" data-set="rpe"><button class="${s.done?'checked':''}" data-action="done" data-i="${i}" data-j="${j}" aria-label="Toggle set ${j+1} complete" aria-pressed="${s.done}">${s.done?'✓':'○'}</button><button data-action="remove-set" data-i="${i}" data-j="${j}" aria-label="Remove set ${j+1}">×</button></div>`).join('')}<button class="secondary" data-action="add-set" data-i="${i}">＋ Add set</button><label>Exercise notes<input maxlength="2000" placeholder="Technique, tempo, how it felt…" value="${esc(e.notes)}" data-i="${i}" data-note></label></section>`).join('')}${!w.exercises.length?'<div class="card empty"><h3>Your session, your way.</h3><p>Add an exercise and log your first set.</p></div>':''}<div class="button-row section-space"><button class="secondary" data-action="add-exercise">＋ Add exercise</button><button class="ghost" data-action="save-routine">Save as routine</button><button class="danger" data-action="discard">Discard session</button></div><label>Session notes<textarea maxlength="2000" data-session="notes" placeholder="A little reflection goes a long way.">${esc(w.notes)}</textarea></label><p class="help">RPE: perceived effort from 1–10. Enter 0 kg for bodyweight movements. Timed movements use seconds; cardio records seconds and kilometres. Older imported plank entries retain their original reps field.</p>`}
function modal(title,html){$('#modal-content').innerHTML=`<div class="modal-heading"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${html}`;$('#modal').showModal()}
function confirmAction(title,text,fn){modal(title,`<p>${esc(text)}</p><div class="button-row section-space"><button class="danger" id="confirm-action">Confirm</button><button class="ghost" data-action="close">Cancel</button></div>`);$('#confirm-action').onclick=()=>{$('#modal').close();fn()}}
function picker(callback){pickerCallback=callback;const available=[...catalog].sort((a,b)=>Number(b.id.startsWith('ft-'))-Number(a.id.startsWith('ft-'))),options=(field)=>[...new Set(available.map(e=>e[field]).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');modal('Find your next movement',`<label for="exercise-search">Search exercises</label><input id="exercise-search" placeholder="Try chest, dumbbell, squat…" autofocus><div class="picker-filters"><label>Equipment<select id="exercise-equipment"><option value="">All equipment</option>${options('equipment')}</select></label><label>Muscle<select id="exercise-muscle"><option value="">All muscles</option>${options('muscle')}</select></label></div><p class="help" id="picker-count"></p><div class="picker" id="picker-list"></div><button type="button" class="secondary" id="picker-more">Load more</button>`);let limit=60;const show=()=>{const q=$('#exercise-search').value.toLowerCase(),eq=$('#exercise-equipment').value,mu=$('#exercise-muscle').value,filtered=available.filter(e=>`${e.name} ${e.muscle} ${e.equipment} ${e.bodyPart||''}`.toLowerCase().includes(q)&&(!eq||e.equipment===eq)&&(!mu||e.muscle===mu));$('#picker-count').textContent=`${filtered.length} movements · showing ${Math.min(limit,filtered.length)}`;$('#picker-list').innerHTML=filtered.slice(0,limit).map(e=>`<div class="picker-item"><button type="button" data-catalog="${esc(e.id)}"><span>${esc(e.name)}<small>${esc(e.muscle)} · ${esc(e.equipment)}</small></span><span>＋</span></button><div class="picker-guides">${guideButton(e)}</div></div>`).join('')||'<p>No exercises match your search.</p>';$('#picker-more').hidden=filtered.length<=limit;$('#picker-list').querySelectorAll('[data-catalog]').forEach(b=>b.onclick=()=>{$('#modal').close();callback(newExercise(catalog.find(e=>e.id===b.dataset.catalog)))})};const reset=()=>{limit=60;show()};$('#exercise-search').oninput=reset;$('#exercise-equipment').onchange=reset;$('#exercise-muscle').onchange=reset;$('#picker-more').onclick=()=>{limit+=60;show()};show()}
function editRoutine(r){let draft=r?structuredClone(r):{id:uid(),name:'New routine',exercises:[]};function show(){modal('Build your routine',`<label for="routine-name">Routine name</label><input id="routine-name" maxlength="200" value="${esc(draft.name)}"><div id="routine-exercises">${draft.exercises.map((e,i)=>`<div class="row"><span>${esc(e.name)}<small class="subtle"> · ${e.sets.length} sets</small></span>${guideButton(e)}<button class="ghost" data-rremove="${i}" aria-label="Remove ${esc(e.name)}">×</button></div>`).join('')}</div><div class="button-row section-space"><button id="routine-add" class="secondary">＋ Exercise</button><button id="routine-save">Save routine</button></div>`);$('#routine-name').oninput=e=>draft.name=e.target.value;$('#routine-add').onclick=()=>{$('#modal').close();picker(e=>{draft.exercises.push(e);show()})};document.querySelectorAll('[data-rremove]').forEach(b=>b.onclick=()=>{draft.exercises.splice(Number(b.dataset.rremove),1);$('#modal').close();show()});$('#routine-save').onclick=()=>{if(!draft.name.trim()||!draft.exercises.length)return toast('Add a name and at least one exercise.');const i=state.routines.findIndex(x=>x.id===draft.id);if(i<0)state.routines.push(draft);else state.routines[i]=draft;save();$('#modal').close();render();toast('Routine saved')}}show()}
function updateTimer(){const el=$('#timer-value');if(!el||!state.active)return;const seconds=Math.max(0,Math.ceil(((state.active.restUntil||0)-Date.now())/1000));el.textContent=seconds?`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`:'Ready'}setInterval(updateTimer,1000);
async function account(kind){modal(kind==='login'?'Welcome back.':'Create your account',`<form id="auth-form"><label for="auth-email">Email</label><input id="auth-email" type="email" required maxlength="254" autocomplete="email"><label for="auth-password">Password (12+ characters)</label><input id="auth-password" type="password" required minlength="12" maxlength="128" autocomplete="${kind==='login'?'current-password':'new-password'}">${kind==='register'?'<label for="setup-token">Server setup token</label><input id="setup-token" type="password" autocomplete="off"><p class="help">Your server administrator provides this token. Registration is closed without it.</p>':''}<p id="auth-error" class="error" role="alert"></p><button class="section-space">${kind==='login'?'Sign in':'Create account'}</button><p class="help">Account mode uses a separate journal. Your local journal is preserved for when you sign out.</p></form>`);$('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const headers={'Content-Type':'application/json'};if(kind==='register')headers['x-setup-token']=$('#setup-token').value;const r=await fetch('/api/auth/'+kind,{method:'POST',headers,body:JSON.stringify({email:$('#auth-email').value,password:$('#auth-password').value})});const data=await r.json();if(!r.ok)throw Error(data.error||'Unable to sign in.');const sr=await fetch('/api/state');if(!sr.ok)throw Error('Unable to load account journal.');const remote=await sr.json();const next=remote.state||empty();if(!valid(next))throw Error('Account data could not be validated.');localStorage.setItem('forge-local-backup',JSON.stringify(state));user=data.user;revision=remote.revision;syncConflict=false;cloudEpoch++;let pending=null;try{pending=JSON.parse(localStorage.getItem('forge-account-'+user.id))}catch{}if(pending&&valid(pending)&&JSON.stringify(pending)!==JSON.stringify(next)){state=pending;syncConflict=true;$('#sync-status').textContent='Unsynced local changes · export then reload'}else{state=next;localStorage.setItem('forge-account-'+user.id,JSON.stringify(state));$('#sync-status').textContent='Account loaded'};$('#modal').close();render();toast('Account journal loaded.')}catch(err){$('#auth-error').textContent=err.message}finally{button.disabled=false}}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;render();window.scrollTo(0,0);return}if(state.active&&page==='session'){let changed=false;document.querySelectorAll('[data-set]').forEach(t=>{const n=t.value===''?null:Number(t.value),f=t.dataset.set,set=state.active.exercises[Number(t.dataset.i)]?.sets[Number(t.dataset.j)];if(!set||(n!==null&&(!Number.isFinite(n)||n<0||n>setLimit(f)))||(n===null&&f!=='rpe'))return;const value=f==='weight'?kg(n):['reps','seconds'].includes(f)?Math.floor(n):n;if(set[f]!==value){set[f]=value;changed=true}});document.querySelectorAll('[data-session]').forEach(t=>{if(state.active[t.dataset.session]!==t.value){state.active[t.dataset.session]=t.value.slice(0,t.dataset.session==='name'?200:2000);changed=true}});document.querySelectorAll('[data-note]').forEach(t=>{const ex=state.active.exercises[Number(t.dataset.i)];if(ex&&ex.notes!==t.value){ex.notes=t.value.slice(0,2000);changed=true}});if(changed)save()}const a=b.dataset.action,i=Number(b.dataset.i),j=Number(b.dataset.j),id=b.dataset.id;if(!a)return;if(demo&&['edit-workout','delete-workout','bodyweight','delete-weight'].includes(a))return toast('Exit sample preview to edit your journal.');switch(a){case'setup':setup();break;case'guide':showGuide(id);break;case'instructions':showInstructions(id);break;case'close':$('#modal').close();break;case'demo':demo=!demo;render();break;case'start':start();break;case'quick-log':quickLog();break;case'add-exercise':picker(x=>{state.active.exercises.push(x);save();render()});break;case'add-set':{const ex=state.active.exercises[i],last=ex.sets.at(-1)||{reps:10,weight:0,rpe:null};ex.sets.push({...last,done:false});save();render();break}case'remove-set':state.active.exercises[i].sets.splice(j,1);save();render();break;case'done':{const s=state.active.exercises[i].sets[j];s.done=!s.done;if(s.done)state.active.restUntil=Date.now()+state.settings.rest*1000;save();render();break}case'remove-exercise':confirmAction('Remove exercise?','Its sets will be removed from this session.',()=>{state.active.exercises.splice(i,1);save();render()});break;case'rest':state.active.restUntil=Date.now()+state.settings.rest*1000;save();updateTimer();break;case'stop-rest':state.active.restUntil=0;save();updateTimer();break;case'finish':if(!sets(state.active).length)return toast('Complete at least one set before finishing.');confirmAction('Finish this workout?',`${sets(state.active).length} completed sets will be saved. Incomplete sets stay in your record and do not count toward totals.`,()=>{const w=state.active;w.finished=w.finished||Date.now();w.restUntil=0;const index=state.workouts.findIndex(x=>x.id===w.id);if(index<0)state.workouts.push(w);else state.workouts[index]=w;state.active=null;save();page='history';render();toast('Workout saved. You showed up.');});break;case'discard':confirmAction('Discard active session?','This cannot be undone.',()=>{state.active=null;save();page='home';render()});break;case'new-routine':editRoutine();break;case'edit-routine':editRoutine(state.routines.find(x=>x.id===id));break;case'delete-routine':confirmAction('Delete routine?','Your completed workouts will remain.',()=>{state.routines=state.routines.filter(x=>x.id!==id);save();render()});break;case'use-routine':{const r=state.routines.find(x=>x.id===id);start(r.exercises.map(x=>({...x,sets:x.sets.map(t=>({...t,done:false}))})),r.name);break}case'template':{const t=templates[Number(id)];editRoutine({id:uid(),name:t.name,exercises:t.ids.map(n=>newExercise(catalog[n]))});break}case'save-routine':if(!state.active.exercises.length)return toast('Add an exercise first.');editRoutine({id:uid(),name:state.active.name,exercises:state.active.exercises.map(x=>({...x,sets:x.sets.map(s=>({...s,done:false}))}))});break;case'edit-workout':if(state.active)return toast('Finish or discard your active workout first.');state.active=structuredClone(state.workouts.find(x=>x.id===id));save();page='session';render();break;case'delete-workout':confirmAction('Delete workout?','This permanently removes this session and recalculates your progress.',()=>{state.workouts=state.workouts.filter(x=>x.id!==id);save();render()});break;case'bodyweight':modal('Log bodyweight',`<form id="weight-form"><label for="bodyweight">Weight (${unit()})</label><input id="bodyweight" type="number" min="1" max="1000" step="0.1" required><button class="section-space">Save entry</button></form>`);$('#weight-form').onsubmit=e=>{e.preventDefault();const n=kg(Number($('#bodyweight').value));if(n<=0||n>1000)return;state.bodyweight.push({id:uid(),date:Date.now(),weight:n});save();$('#modal').close();render()};break;case'delete-weight':confirmAction('Delete bodyweight entry?','This entry will be removed.',()=>{state.bodyweight=state.bodyweight.filter(x=>x.id!==id);save();render()});break;case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='forge-backup-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break}case'import':$('#import-file').click();break;case'clear':confirmAction('Clear your journal?','This removes workouts, routines, bodyweight and active session. Export a backup first. This cannot be undone.',()=>{state=empty();save();render()});break;case'reload-account':confirmAction('Reload account journal?','Export any pending local changes first. This replaces the working copy with server data.',async()=>{try{await syncQueue;const r=await fetch('/api/state');if(!r.ok)throw Error();const d=await r.json();if(!valid(d.state||empty()))throw Error();state=d.state||empty();revision=d.revision;syncConflict=false;localStorage.setItem('forge-account-'+user.id,JSON.stringify(state));$('#sync-status').textContent='Account loaded';render();toast('Account journal reloaded.')}catch{toast('Unable to reload account journal.')}});break;case'login':account('login');break;case'register':account('register');break;case'logout':{await syncQueue;const r=await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)return toast('Sign out failed. Try again when connected.');cloudEpoch++;user=null;syncConflict=false;revision=0;try{state=JSON.parse(localStorage.getItem(KEY))||JSON.parse(localStorage.getItem('forge-local-backup'))||empty()}catch{state=empty()}if(!valid(state))state=empty();localStorage.removeItem('forge-local-backup');save();render();toast('Signed out. Your local journal is restored.');break}case'install':if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast('Safari: Share → Add to Home Screen. Other browsers: Install app.');break;}});
document.addEventListener('input',e=>{const t=e.target;if(!state.active)return;let changed=false;if(t.dataset.set){const n=t.value===''?null:Number(t.value),field=t.dataset.set,set=state.active.exercises[Number(t.dataset.i)]?.sets[Number(t.dataset.j)];if(!set)return;if(field==='rpe'){if(n!==null&&(!Number.isFinite(n)||n<0||n>10))return;set.rpe=n}else{if(n===null||!Number.isFinite(n)||n<0||n>setLimit(field))return;set[field]=field==='weight'?kg(n):['reps','seconds'].includes(field)?Math.floor(n):n}changed=true}if(t.dataset.session){state.active[t.dataset.session]=t.value.slice(0,t.dataset.session==='name'?200:2000);changed=true}if(t.hasAttribute('data-note')){state.active.exercises[Number(t.dataset.i)].notes=t.value.slice(0,2000);changed=true}if(changed)save()});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.set){const n=t.value===''?null:Number(t.value),field=t.dataset.set,s=state.active.exercises[Number(t.dataset.i)].sets[Number(t.dataset.j)];if(field==='rpe'){if(n!==null&&(!Number.isFinite(n)||n<0||n>10)){toast('RPE must be between 0 and 10.');render();return}s.rpe=n}else{if(n===null||!Number.isFinite(n)||n<0||n>setLimit(field)){toast('Enter a valid positive number.');render();return}s[field]=field==='weight'?kg(n):['reps','seconds'].includes(field)?Math.floor(n):n}save()}if(t.dataset.session){state.active[t.dataset.session]=t.value.slice(0,t.dataset.session==='name'?200:2000);save()}if(t.hasAttribute('data-note')){state.active.exercises[Number(t.dataset.i)].notes=t.value.slice(0,2000);save()}if(t.id==='unit'){state.settings.unit=t.value;save();render()}if(t.id==='rest'){state.settings.rest=Math.min(600,Math.max(0,Number(t.value)||0));save();render()}if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>450000)throw Error('Backup exceeds the 450 KB limit.');const imported=JSON.parse(await t.files[0].text());if(!valid(imported))throw Error('This is not a valid FORGE v1 backup.');confirmAction('Replace your journal?',`Import ${imported.workouts.length} workouts and ${imported.routines.length} routines? Your current journal will be replaced.`,()=>{state=imported;save();render();toast('Backup imported.')})}catch(err){toast(err.message)}t.value=''}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('online',()=>{if(user)save()});render();queueMicrotask(()=>{if(!state.profile&&!state.workouts.length&&!state.routines.length&&!state.active&&!localStorage.getItem('forge-setup-skipped'))setup()});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
(async()=>{const initialMutation=mutationCount;try{const r=await fetch('/api/auth/me');if(!r.ok)return;const d=await r.json(),s=await fetch('/api/state');if(!s.ok)return;const remote=await s.json();if(!valid(remote.state||empty()))return;if(mutationCount!==initialMutation){toast('Sign in through Settings to load your account after these local changes.');return}user=d.user;revision=remote.revision;try{cachedAccount=JSON.parse(localStorage.getItem('forge-account-'+user.id))||cachedAccount}catch{cachedAccount=null}if(cachedAccount&&JSON.stringify(cachedAccount)!==JSON.stringify(remote.state||empty())){state=cachedAccount;syncConflict=true;$('#sync-status').textContent='Unsynced local changes · export then reload';toast('Local and account journals differ. Export your local journal before reloading account data.');render();return}if(localStorage.getItem('forge-mode')!=='account')localStorage.setItem('forge-local-backup',JSON.stringify(state));state=remote.state||empty();localStorage.setItem('forge-mode','local');localStorage.setItem('forge-account-'+user.id,JSON.stringify(state));$('#sync-status').textContent='Account loaded';render()}catch{}})();

function guideButton(e){const instructions=catalog.find(c=>c.id===e.id)?.instructions;return (demoNames[e.demoKey]?`<button type="button" class="ghost guide-button" data-action="guide" data-id="${e.demoKey}" aria-label="View movement guide for ${esc(e.name)}">▷ Guide</button>`:'')+(Array.isArray(instructions)&&instructions.length?`<button type="button" class="ghost guide-button" data-action="instructions" data-id="${esc(e.id)}" aria-label="View exercise instructions for ${esc(e.name)}">Instructions</button>`:'')}
function showInstructions(id){const e=catalog.find(c=>c.id===id);if(!e||!Array.isArray(e.instructions))return;const previous=Array.from($('#modal-content').childNodes),wasOpen=$('#modal').open;modal(esc(e.name),`<span class="tag">EXERCISE INSTRUCTIONS</span><ol class="guide-cues">${e.instructions.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><p class="help">General exercise instructions from the OpenGym metadata catalogue. This guide is not personalized; adjust with a qualified trainer when needed. Stop if movement causes pain.</p>${wasOpen?'<button type="button" class="ghost section-space" id="instructions-back">Back</button>':''}`);if(wasOpen)$('#instructions-back').onclick=()=>$('#modal-content').replaceChildren(...previous)}
function showGuide(key){if(!demoNames[key])return;const previous=Array.from($('#modal-content').childNodes),wasOpen=$('#modal').open;let paused=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const cues={squat:['Feet in a comfortable stance; lower only as far as you can control.','Keep your knees tracking with your toes; stand smoothly.'],pushup:['Hands under or slightly outside shoulders; keep your trunk steady.','Lower with control. Use a wall or incline to make this easier.'],row:['Support your torso; keep your spine in a comfortable neutral position.','Pull the elbow toward the hip without twisting; lower slowly.'],hinge:['Soften the knees and send the hips back.','Keep the load close; stop before your back position changes.'],bridge:['Lie on your back with knees bent and feet planted.','Raise the hips smoothly without arching the lower back.'],deadbug:['Lie on your back and brace gently.','Extend opposite arm and leg only as far as you can keep your trunk steady.']};modal(demoNames[key],`<span class="tag">SCHEMATIC MOVEMENT GUIDE</span><img class="movement-demo" id="movement-demo" src="/demos/${key}.${paused?'png':'gif'}" alt="Animated schematic demonstrating the ${esc(demoNames[key])} movement pattern"><button class="secondary" id="guide-toggle">${paused?'Play animation':'Pause animation'}</button><ul class="guide-cues">${cues[key].map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p class="help">An original simplified illustration of a movement pattern; your exercise variant may differ. It cannot assess your individual technique. Start within a comfortable range; stop if you feel pain.</p>${wasOpen?'<button class="ghost section-space" id="guide-back">Back</button>':''}`);$('#guide-toggle').onclick=()=>{paused=!paused;$('#movement-demo').src=`/demos/${key}.${paused?'png':'gif'}`;$('#guide-toggle').textContent=paused?'Play animation':'Pause animation'};if(wasOpen)$('#guide-back').onclick=()=>{$('#modal-content').replaceChildren(...previous)} }
let setupDraft=null,setupStep=0,pickerCallback=null,reviewedSessions=[];
function planCard(s){if(!s.profile)return `<section class="card plan-card"><div><span class="tag">BUILT AROUND YOU</span><h2>Find your starting point.</h2><p>Choose a goal, time and equipment. Get a plan you can adapt.</p></div><button class="secondary" data-action="setup">Personalize training ↗</button></section>`;const rec=ForgeTraining.recommend(s.profile),reasons=Array.isArray(rec.rationale)?rec.rationale:[rec.rationale],saved=s.profilePlanIds?s.routines.filter(r=>s.profilePlanIds.includes(r.id)):s.routines.filter(r=>r.name.startsWith('FORGE /'));return `<section class="card plan-card"><div><span class="tag">YOUR PLAN / ${esc(s.profile.goal==='fatLoss'?'FITNESS & FAT LOSS':s.profile.goal.toUpperCase())}</span><h2>${esc(rec.summary)}</h2><div class="button-row">${saved.slice(0,4).map(r=>`<button class="secondary" data-action="use-routine" data-id="${esc(r.id)}">Start ${esc(r.name.replace('FORGE / ',''))}</button>`).join('')}</div><p>${esc(reasons[0]||'Your editable starting point, matched to your available time and equipment.')}</p><details class="plan-details"><summary>Why this plan & how to progress</summary><ul>${reasons.filter(Boolean).map(reason=>`<li>${esc(reason)}</li>`).join('')}</ul><p>${esc(rec.loadHint)}</p><p>${esc(rec.progressionHint)}</p><p>${esc(rec.activityHint)}</p><p class="help">${esc(rec.notice)}</p></details>${!rec.eligible?`<p class="notice">${esc(rec.notice)}</p>`:''}</div><button class="ghost" data-action="setup">Edit profile ↗</button></section>`}
function setup(step=0,reset=true){if(step===0&&reset)setupDraft={version:1,ageGroup:'adult',weightKg:null,heightCm:null,goal:'fitness',experience:'beginner',days:3,minutes:30,equipment:'bodyweight',impact:'standard',limitations:'',bodyFocus:'balanced',...state.profile};setupStep=step;const select=(id,label,options)=>`<label for="p-${id}">${label}</label><select id="p-${id}" name="${id}">${options.map(([v,l])=>`<option value="${v}" ${String(setupDraft[id])===String(v)?'selected':''}>${l}</option>`).join('')}</select>`;let body='';if(step===0)body=`<p class="subtle">Make a starting plan that fits your actual week. Change any choice later.</p><div class="setup-fields">${select('goal','What are you working toward?',[['fitness','Everyday fitness'],['strength','Build strength'],['muscle','Build muscle'],['fatLoss','Support fat loss']])}${select('experience','Your training experience',[['beginner','Getting started'],['returning','Returning to training'],['experienced','Training regularly']])}${select('days','Sessions per week',[2,3,4,5,6].map(n=>[n,n+' sessions']))}${select('minutes','Time per session',[20,30,45,60].map(n=>[n,n+' minutes']))}${select('equipment','Available equipment',[['bodyweight','Bodyweight only'],['dumbbells','Dumbbells'],['gym','Full gym']])}${select('bodyFocus','Training emphasis',[['balanced','Balanced, whole body'],['upper','Upper body emphasis'],['lower','Lower body emphasis'],['core','Core emphasis']])}</div>`;else if(step===1)body=`<p class="subtle">Measurements are optional. Body shape alone does not determine training. We use experience, equipment and your needs.</p><div class="setup-fields">${select('ageGroup','Age group',[['adult','Adult (18–64)'],['under18','Under 18'],['older','65 or older']])}${select('impact','Movement preference',[['standard','Standard impact'],['low','Lower impact']])}<label for="p-weightKg">Bodyweight in kg (optional)</label><input name="weightKg" id="p-weightKg" type="number" min="20" max="400" step="0.1" value="${setupDraft.weightKg??''}"><label for="p-heightCm">Height in cm (optional)</label><input name="heightCm" id="p-heightCm" type="number" min="80" max="250" value="${setupDraft.heightCm??''}"></div><label for="p-limitations">Injuries, movement restrictions or other needs (optional)</label><textarea name="limitations" id="p-limitations" maxlength="500" placeholder="A trainer can help adapt a plan to these needs.">${esc(setupDraft.limitations)}</textarea><p class="help">This information stays in your journal and syncs only if you enable an account. It is not used to estimate a starting lifting weight.</p>`;else{let rec;try{setupDraft=ForgeTraining.validateProfile(setupDraft);rec=ForgeTraining.recommend(setupDraft)}catch(err){toast(err.message);return setup(1)}reviewedSessions=structuredClone(rec.sessions);body=`<p class="subtle">${esc(rec.summary)}</p><p>${esc(Array.isArray(rec.rationale)?rec.rationale.join(' '):rec.rationale)}</p>${rec.sessions.map((r,ri)=>`<section class="plan-preview"><label for="review-name-${ri}">Routine name</label><input id="review-name-${ri}" data-plan-name="${ri}" maxlength="180" value="${esc(r.name)}">${r.exercises.map((e,ei)=>`<div class="review-exercise"><label class="review-check"><input type="checkbox" data-plan-keep="${ri}:${ei}" checked> ${esc(e.name)}</label>${guideButton(e)}<label>Sets<input data-plan-sets="${ri}:${ei}" type="number" min="1" max="10" required value="${e.sets.length}"></label><label>Reps<input data-plan-reps="${ri}:${ei}" type="number" min="1" max="100" required value="${e.sets[0]?.reps||10}"></label></div>`).join('')}</section>`).join('')}<div class="notice">${esc(rec.notice)}<br>${esc(rec.loadHint)}<br>${esc(rec.progressionHint)}<br>${esc(rec.activityHint)}</div><p class="help">Applying adds new routines. Edit them in Routines before training. Existing sessions and routines remain available.</p>`}modal(`Your training, personalized.`, `<div class="setup-progress"><span class="${step===0?'current':''}">1 · Preferences</span><span class="${step===1?'current':''}">2 · About you</span><span class="${step===2?'current':''}">3 · Your plan</span></div><form id="setup-form">${body}<p id="setup-error" class="error" role="alert"></p><div class="button-row section-space">${step?'<button type="button" class="ghost" id="setup-back">Back</button>':''}<button type="submit">${step===2?(ForgeTraining.recommend(setupDraft).eligible?'Save profile & add plan':'Save profile & use logger'):'Continue ↗'}</button><button type="button" class="ghost" id="setup-skip">Skip & use logger</button></div></form>`);$('#setup-skip').onclick=()=>{localStorage.setItem('forge-setup-skipped','1');setupDraft=null;$('#modal').close()};if(step)$('#setup-back').onclick=()=>setup(step-1,false);$('#setup-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);for(const [k,v] of f){setupDraft[k]=['days','minutes'].includes(k)?Number(v):['weightKg','heightCm'].includes(k)?(v===''?null:Number(v)):v}if(step<2){try{setupDraft=ForgeTraining.validateProfile(setupDraft);setup(step+1)}catch(err){$('#setup-error').textContent=err.message}return}const rec=ForgeTraining.recommend(setupDraft);const sessions=reviewedSessions.map((r,ri)=>({...r,name:$(`[data-plan-name="${ri}"]`).value.trim()||r.name,exercises:r.exercises.filter((e,ei)=>$(`[data-plan-keep="${ri}:${ei}"]`).checked).map(e=>{const ei=r.exercises.indexOf(e),count=Number($(`[data-plan-sets="${ri}:${ei}"]`).value),reps=Number($(`[data-plan-reps="${ri}:${ei}"]`).value);return {...e,sets:Array.from({length:count},()=>({...e.sets[0],reps,done:false}))}})})).filter(r=>r.exercises.length);if(rec.eligible&&!sessions.length){$('#setup-error').textContent='Keep at least one exercise in your plan.';return}const added=sessions.map(r=>({id:uid(),name:'GYM / '+r.name,exercises:r.exercises.map(e=>({...e,id:String(e.id||uid()),notes:e.notes||'',sets:e.sets.map(t=>({reps:t.reps,weight:t.weight||0,rpe:t.rpe??null,done:false}))}))}));if(state.routines.length+added.length>1000){$('#setup-error').textContent='Routine limit reached. Remove unused routines first.';return}state.profile=structuredClone(setupDraft);state.profilePlanIds=added.map(r=>r.id);state.routines.push(...added);save();setupDraft=null;$('#modal').close();render();toast(added.length?'Profile saved. Your editable plan is in Routines.':'Profile saved. Continue logging your own training.')}}

function setLimit(field){return field==='rpe'?10:field==='seconds'?86400:field==='distanceKm'?1000:10000}
